BEGIN;
CREATE TABLE IF NOT EXISTS vendors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES entities(id),vendor_code varchar(50) NOT NULL,name varchar(255) NOT NULL,email varchar(320),phone varchar(50),tax_id_encrypted text,is_1099_required boolean NOT NULL DEFAULT false,payment_terms_days integer NOT NULL DEFAULT 30 CHECK(payment_terms_days>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,vendor_code));
CREATE TABLE IF NOT EXISTS vendor_bills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES entities(id),vendor_id uuid NOT NULL REFERENCES vendors(id),bill_number varchar(60) NOT NULL,bill_date date NOT NULL,due_date date NOT NULL,currency char(3) NOT NULL,total_amount numeric(20,2) NOT NULL CHECK(total_amount>0),status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','SUBMITTED','APPROVED','PARTIALLY_PAID','PAID','VOID')),prepared_by uuid REFERENCES users(id),approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,vendor_id,bill_number));
CREATE TABLE IF NOT EXISTS vendor_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vendor_bill_id uuid NOT NULL REFERENCES vendor_bills(id),payment_date date NOT NULL,amount numeric(20,2) NOT NULL CHECK(amount>0),reference varchar(100),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_vendor_bills_due ON vendor_bills(entity_id,due_date,status);
COMMIT;
